class Key:
 def __index__(self): raise AssertionError('converted')
k=Key();values={k:1};values[k]+=2
print(values[k])

class Box:
 def __getitem__(self,key): self.key=key;return [1]
 def __setitem__(self,key,value): print(key is self.key,value)
k=slice('a','b','c');Box()[k]+=[2]

def rhs(): raise AssertionError('rhs ran')
def run(items,key): items[key]+=rhs()
try: run({},'missing')
except KeyError: print('missing')

value=[];items=(value,)
try: items[0]+=[2]
except TypeError: print(value,items[0] is value)

events=[]
class Box:
 def __getitem__(self,key): events.append('get');return 1
 def __setitem__(self,key,value): events.append('old')
def setter(self,key,value): events.append(('new',value))
def rhs(): Box.__setitem__=setter;return 2
Box()[0]+=rhs()
print(events)
